import * as THREE from 'three';
import { particles } from 'wgpu-kit/particles';
import { threePoints, type ThreeAPI } from 'wgpu-kit/three';
const sim = await particles({ count: 1024 });
const handle = threePoints(sim, THREE as unknown as ThreeAPI, { size: 0.02 });
const points = handle.points as THREE.Points;
const scene = new THREE.Scene();
scene.add(points);
await handle.update(); // Initial snapshot; no tick has changed the buffer.
// Render scene with your camera and renderer.
function dispose() {
  scene.remove(points);
  points.geometry.dispose();
  const materials = Array.isArray(points.material) ? points.material : [points.material];
  materials.forEach(material => material.dispose());
  handle.dispose(); // Also destroys sim.
}
